CREATE TABLE tbl(a,b PRIMARY KEY) WITHOUT ROWID; CREATE TABLE rlog(idx,old_a,old_b,db_sum_a,db_sum_b,new_a,new_b); CREATE TRIGGER insert_before_row BEFORE INSERT ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),0,0,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END; CREATE TRIGGER insert_after_row AFTER INSERT ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),0,0,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END;